S = "Hakeem Force Academy"
QS = [
(S, "The straight line given by the equation y = 6x passes through which point?", ["The origin (0, 0)", "The point (0, 6)", "The point (6, 0)", "The point (1, 1)"], 0, "Putting x = 0 gives y = 6 times 0 = 0, so the line passes through (0, 0). Every line of the form y = mx passes through the origin.", "In y = mx, the number m is the slope of the line, which is 6 here.", [5493]),
(S, "A quadratic equation is also called an equation of which degree?", ["First degree", "Second degree", "Third degree", "Zero degree"], 1, "A quadratic equation has the highest power of the variable equal to 2, so it is a second degree equation.", "A linear equation is first degree and a cubic equation is third degree.", [1644]),
(S, "Is the expression 2x + 3x + 1 = 0 a linear equation?", ["Yes, because it simplifies to 5x + 1 = 0", "No, because it has three terms", "No, because it has two x terms", "No, because it is quadratic"], 0, "Adding the like terms gives 5x + 1 = 0. The highest power of x is 1, so it is a linear equation.", "A linear equation in one variable has exactly one root.", [2781]),
(S, "What is the degree of a linear equation?", ["0", "1", "2", "3"], 1, "In a linear equation the highest power of the variable is 1, so its degree is 1.", "The graph of a linear equation in two variables is a straight line.", [3594]),
(S, "What is the process by which a liquid changes into vapour (gas) called?", ["Condensation", "Sublimation", "Evaporation", "Freezing"], 2, "When a liquid gains heat and its molecules escape into the air as vapour, the change is called evaporation or vaporization.", "The reverse process, vapour changing into liquid, is called condensation.", [3559, 3898, 4839]),
(S, "Which region of Pakistan is commonly called Little Tibet?", ["Baltistan", "Chitral", "Swat", "Hunza"], 0, "Baltistan, with its capital Skardu, resembles Tibet in culture, language and landscape, so it is called Little Tibet.", "Ladakh in India is also sometimes called Little Tibet.", [4828]),
(S, "For about how many years did the Holy Prophet (PBUH) live in Makkah after the first revelation (wahi) before the Hijrat?", ["10 years", "13 years", "23 years", "40 years"], 1, "The first wahi came when the Prophet (PBUH) was 40 years old. He stayed in Makkah for about 13 more years and migrated to Madina at the age of 53.", "He then lived about 10 years in Madina.", [2003]),
(S, "What is the value of log 1 (to any valid base)?", ["1", "0", "10", "Undefined"], 1, "Any base b raised to the power 0 equals 1, so the logarithm of 1 is 0.", "The logarithm of 0 is undefined.", [3393]),
(S, "Which is the longest river lying entirely within Afghanistan?", ["Helmand", "Kabul", "Amu Darya", "Hari Rud"], 0, "The Helmand River, about 1,150 km long, is the longest river that flows wholly in Afghanistan.", "The Amu Darya forms part of the northern border with Central Asia, so it is not counted as entirely Afghan; some sources differ.", [148]),
(S, "Which is the longest Surah of the Holy Quran?", ["Al-Baqarah", "Al-Imran", "An-Nisa", "Al-Kahf"], 0, "Surah Al-Baqarah has 286 verses and is the longest Surah of the Quran.", "The shortest Surah is Al-Kawthar with 3 verses.", [3727]),
(S, "Which is the longest freshwater lake in the world?", ["Lake Tanganyika", "Lake Victoria", "Lake Superior", "Lake Baikal"], 0, "Lake Tanganyika in Africa is about 673 km long, the longest freshwater lake in the world.", "Lake Baikal is the deepest lake, and Lake Superior is the largest freshwater lake by area.", [1330]),
(S, "Which is the longest river entirely in England?", ["River Thames", "River Severn", "River Trent", "River Mersey"], 0, "The Thames, about 346 km long, is the longest river wholly in England.", "The Severn is longer overall (354 km) but part of it flows through Wales.", [4666]),
(S, "Who was Lord Curzon at the time of the partition of Bengal in 1905?", ["Viceroy of India", "Governor of Bengal", "Secretary of State for India", "Commander-in-Chief of India"], 0, "Lord Curzon was the Viceroy and Governor-General of India from 1899 to 1905 and he carried out the partition of Bengal in 1905.", "The partition was annulled in 1911.", [5307]),
(S, "What is the antonym (opposite) of the word 'loved'?", ["Hated", "Liked", "Adored", "Cherished"], 0, "Loved means felt strong affection for, and its opposite is hated.", "Loathed and detested are other close opposites.", [1082, 3868]),
(S, "Who designed the Minar-e-Pakistan in Lahore?", ["Nasreddin Murat-Khan", "Sir Ganga Ram", "Ahmad Ali Lahori", "Shahid Hamid"], 0, "The Minar-e-Pakistan was designed by the Russian-born architect Nasreddin Murat-Khan.", "It was built in Iqbal Park, Lahore, where the Lahore Resolution was passed in 1940.", [5223]),
(S, "How many Madni surahs are there in the Holy Quran according to the common Pakistani textbook count?", ["28", "86", "114", "40"], 0, "The Quran has 114 surahs, of which 86 are Makki and 28 are Madni.", "Madni surahs were revealed after the Hijrat to Madina.", [843, 290, 3854]),
(S, "Which is the main river of Khyber Pakhtunkhwa?", ["Kabul River", "Jhelum", "Ravi", "Sutlej"], 0, "The Kabul River flows from Afghanistan through Khyber Pakhtunkhwa and joins the Indus near Attock.", "The Swat River is a tributary of the Kabul River.", [3318, 3730]),
(S, "What is the main religion of Pakistan?", ["Islam", "Hinduism", "Christianity", "Sikhism"], 0, "About 96 percent of Pakistanis are Muslims, so Islam is the main religion and the state religion.", "Article 2 of the Constitution declares Islam the state religion of Pakistan.", [3729]),
(S, "On which date is the Mairaj (Shab-e-Mairaj) commemorated?", ["27 Rajab", "12 Rabi-ul-Awwal", "27 Ramadan", "15 Shaban"], 0, "The night journey and ascension of the Prophet (PBUH) is observed on the night of 27 Rajab.", "Shab-e-Barat is on 15 Shaban.", [1542]),
(S, "Which pillar of Islam was made obligatory on the Prophet (PBUH) during the Mairaj?", ["Salah (prayer)", "Fasting", "Zakat", "Hajj"], 0, "Five daily prayers were gifted to the Muslims on the night of Mairaj, after being reduced from fifty.", "The journey from Makkah to Bait-ul-Muqaddas is called Isra and the ascension to the heavens is called Mairaj.", [4827]),
(S, "Which Surah is called the heart of the Quran?", ["Surah Yaseen", "Surah Al-Fatiha", "Surah Al-Ikhlas", "Surah Ar-Rahman"], 0, "A well known hadith calls Surah Yaseen the heart of the Quran.", "Surah Al-Fatiha is called the Mother of the Book (Umm-ul-Kitab).", [1544]),
(S, "Which Sahabi is the only companion whose name is mentioned in the Quran?", ["Hazrat Zaid bin Harithah (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)"], 0, "Surah Al-Ahzab (verse 37) mentions Zaid bin Harithah (RA) by name.", "The Quran mentions Prophet Muhammad (PBUH) by name four times.", [4918]),
(S, "Which Air Force rank is equivalent to the Army rank of Major?", ["Squadron Leader", "Flight Lieutenant", "Wing Commander", "Group Captain"], 0, "Squadron Leader equals Major in the Army and Lieutenant Commander in the Navy.", "Wing Commander equals Lieutenant Colonel.", [4407]),
(S, "Who was the first woman promoted to the rank of Major General in the Pakistan Army?", ["Shahida Malik", "Nigar Johar", "Shahida Badshah", "Shamim Wynne"], 0, "Dr Shahida Malik, a medical doctor, became the first woman Major General in 2002.", "Nigar Johar became the first woman Lieutenant General in 2020.", [5338]),
(S, "Which party won a majority of seats in East Pakistan in the 1970 general elections?", ["Awami League", "Pakistan People's Party", "Muslim League", "Jamaat-e-Islami"], 0, "The Awami League led by Sheikh Mujibur Rahman won 160 of the 162 East Pakistan seats.", "The Pakistan People's Party won the most seats in West Pakistan.", [4814]),
(S, "A tangent to a circle makes what angle with the radius drawn to the point of contact?", ["30 degrees", "45 degrees", "60 degrees", "90 degrees"], 3, "A tangent is always perpendicular to the radius at the point of contact, so the angle is 90 degrees.", "From an external point two tangents of equal length can be drawn to a circle.", [3005]),
(S, "What was the old name of Makkah?", ["Bakkah", "Yathrib", "Taif", "Tayyibah"], 0, "Makkah was also called Bakkah, a name mentioned in Surah Al-Imran.", "Madina was earlier known as Yathrib.", [222]),
(S, "Who is the current Prime Minister of Malaysia (October 2026)?", ["Anwar Ibrahim", "Ismail Sabri Yaakob", "Mahathir Mohamad", "Muhyiddin Yassin"], 0, "Anwar Ibrahim became the 10th Prime Minister of Malaysia in November 2022 and is still in office in 2026.", "Ismail Sabri Yaakob was PM from 2021 to 2022, when candidates took the test.", [203, 117, 3525]),
(S, "What is the capital of Malaysia?", ["Kuala Lumpur", "Putrajaya", "Johor Bahru", "George Town"], 0, "Kuala Lumpur is the capital and largest city of Malaysia.", "Putrajaya is the administrative capital where government offices are located.", [1098]),
(S, "Malaysia has a king instead of a president. Who is the head of state (Yang di-Pertuan Agong) of Malaysia in 2026?", ["Sultan Ibrahim of Johor", "Sultan Abdullah of Pahang", "Sultan Nazrin Shah of Perak", "Anwar Ibrahim"], 0, "Malaysia is a constitutional monarchy with no president. Sultan Ibrahim of Johor has been the 17th Agong since 31 January 2024.", "His predecessor was Sultan Abdullah of Pahang, who was Agong from 2019 to 2024.", [5140, 92]),
(S, "Between which two countries does the Line of Control (LOC) lie?", ["India and Pakistan", "Pakistan and Afghanistan", "India and China", "Pakistan and China"], 0, "The Line of Control is the de facto military border dividing Indian-administered and Pakistan-administered Kashmir.", "It was established by the Simla Agreement of 1972.", [139, 3044, 4488]),
(S, "What does LOC stand for?", ["Line of Control", "Line of Command", "Limit of Control", "Line of Conflict"], 0, "LOC stands for Line of Control, the ceasefire line in Kashmir between India and Pakistan.", "It began as the 1949 Ceasefire Line and was renamed after the 1972 Simla Agreement.", [330, 562]),
(S, "What is the approximate length of the Line of Control (LOC) between India and Pakistan?", ["About 740 km", "About 1,200 km", "About 2,000 km", "About 400 km"], 0, "The Line of Control runs for about 740 km through Kashmir.", "The whole international border plus the LOC and Working Boundary is about 3,300 km.", [1131]),
(S, "On which river is Dushanbe, the capital of Tajikistan, located?", ["Varzob River", "Amu Darya", "Syr Darya", "Zarafshan"], 0, "Dushanbe lies in the Gissar valley on the Varzob River, which is called Dushanbinka within the city.", "Dushanbe is the capital of Tajikistan, not a European city.", [2915]),
(S, "In which mountain range is the Siachen Glacier located?", ["Karakoram range", "Hindu Kush", "Pir Panjal", "Sulaiman range"], 0, "The Siachen Glacier lies in the eastern Karakoram range in the disputed Kashmir region.", "It is about 76 km long and is among the longest glaciers outside the polar regions.", [4383]),
(S, "In which direction does Iran lie with respect to Pakistan?", ["West", "East", "North", "South"], 0, "Iran borders Pakistan along its western side, mostly the Balochistan province.", "The Pakistan-Iran border is about 959 km long.", [3720]),
(S, "Who is the current President of the United States living in the White House (October 2026)?", ["Donald Trump", "Joe Biden", "Barack Obama", "Kamala Harris"], 0, "Donald Trump began his second term as US President on 20 January 2025 and lives in the White House.", "Joe Biden was President from 2021 to 2025, when candidates took the test.", [5220]),
(S, "Which people lived in Khyber (Khaybar) at the time of the Prophet (PBUH)?", ["Jews", "Christians", "Quraish", "Persians"], 0, "Khaybar was a fortified oasis north of Madina inhabited by Jewish tribes, and they were defeated in 7 AH.", "The Battle of Khyber was fought in 7 Hijri.", [5219]),
]
